var numbers = new[] { 1, 2, 3, 4, 5 };

// LINQ (C#)
var doubled = numbers.Select(x => x * 2).ToList();
var evens   = numbers.Where(x => x % 2 == 0).ToList();
var sum     = numbers.Aggregate(0, (acc, x) => acc + x);

// 메서드 체이닝
var result = numbers
    .Where(x => x % 2 == 0)
    .Select(x => x * x)
    .Sum();
